<script lang="ts">
  import { chains } from '$lib/config/chains'; import { onMount } from 'svelte'; import WalletAuth from '$components/WalletAuth.svelte';
  let query = '';
  let activeChain: (typeof chains)[number] = chains[0];
  let tab: 'portfolio'|'activity'|'nfts' = 'portfolio';
  let chatOpen = false;
  let reportOpen = false;
  let scamOpen = false;
  let chatInput = '';
  let messages: {role:'user'|'assistant';content:string}[] = [{role:'assistant',content:'Ask me about the wallet, chain, transaction, or risk evidence currently on screen.'}];
  let report = '';
  let reportHash = '';
  let inspectedAddress = '';
  let balances: Array<{chainId:number;name:string;symbol:string;amount:string;status:string;error?:string}> = [];
  let loading = false;
  let notice = 'Enter a 0x address, transaction hash, or block number.';
  let explorerResult: Record<string, unknown> | null = null;
  let riskEvidence: Array<{label:string;status:string;detail:string}> = [];
  let walletAddress = '';
  let chatLoading = false;
  let plan: 'free'|'premium' = 'free'; let reportUsage = 0; let proofSaved = false;
  let scamUsage=0;let scamTarget='';let scamDescription='';let scamLoading=false;let scamError='';let scamResult:{riskLevel:string;confidence:string;scamType:string;summary:string;evidence:string[];avoidance:string[];protection:string[];missingInformation:string[];disclaimer:string}|null=null;
  let evidenceFiles: Array<{id:string;name:string;size:number;type:string;hash:string}> = []; let fileError=''; let hashingFiles=false;
  $: reportLimit = plan === 'premium' ? 100 : 5;
  $: scamLimit = plan === 'premium' ? 100 : 5;
  $: fileLimit = plan === 'premium' ? 20 : 5;
  onMount(()=>{plan=(localStorage.getItem('poke-plan')==='premium'?'premium':'free');reportUsage=Number(localStorage.getItem('poke-report-usage')||0);scamUsage=Number(localStorage.getItem('poke-scam-usage')||0);});

  async function inspect() {
    if (!query.trim()) return;
    loading=true; notice='Querying live testnet data…'; explorerResult=null;
    try {
      if (/^0x[a-fA-F0-9]{40}$/.test(query.trim())) {
        const response=await fetch(`/api/portfolio?address=${encodeURIComponent(query.trim())}`); const data=await response.json();
        if(!response.ok) throw new Error(data.error); inspectedAddress=data.address; balances=data.balances; notice=`Updated ${new Date(data.fetchedAt).toLocaleTimeString()}`;
        const risk=await fetch(`/api/scam-score?target=${encodeURIComponent(query.trim())}`).then(r=>r.json()); riskEvidence=risk.evidence;
      } else {
        const response=await fetch(`/api/explorer?chainId=${activeChain.id}&query=${encodeURIComponent(query.trim())}`); const data=await response.json();
        if(!response.ok) throw new Error(data.error); explorerResult=data.result; tab='activity'; notice=`Live ${data.type} loaded from ${activeChain.name}`;
      }
    } catch(error) { notice=error instanceof Error?error.message:'Request failed'; }
    finally { loading=false; }
  }
  async function connectWallet() { try { const ethereum=(window as unknown as {ethereum?:{request:(args:{method:string})=>Promise<string[]>}}).ethereum; if(!ethereum) throw new Error('Install an EVM wallet such as MetaMask.'); const accounts=await ethereum.request({method:'eth_requestAccounts'}); walletAddress=accounts[0]||''; query=walletAddress; if(walletAddress) await inspect(); } catch(error){notice=error instanceof Error?error.message:'Wallet connection failed';} }
  function hex(buffer:ArrayBuffer){return '0x'+[...new Uint8Array(buffer)].map(x=>x.toString(16).padStart(2,'0')).join('');}
  async function addEvidence(event:Event){const input=event.currentTarget as HTMLInputElement;const selected=Array.from(input.files||[]);fileError='';if(evidenceFiles.length+selected.length>fileLimit){fileError=`Your ${plan} plan allows ${fileLimit} files per report.`;input.value='';return;}const allowed=['image/png','image/jpeg','image/webp','application/pdf','text/plain','application/json'];if(selected.some(file=>!allowed.includes(file.type))){fileError='Use PNG, JPG, WEBP, PDF, TXT, or JSON files only.';input.value='';return;}if(selected.some(file=>file.size>10*1024*1024)){fileError='Each evidence file must be 10 MB or smaller.';input.value='';return;}hashingFiles=true;for(const file of selected){const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());evidenceFiles=[...evidenceFiles,{id:crypto.randomUUID(),name:file.name,size:file.size,type:file.type,hash:hex(digest)}];}hashingFiles=false;input.value='';reportHash='';proofSaved=false;}
  function removeEvidence(id:string){evidenceFiles=evidenceFiles.filter(file=>file.id!==id);reportHash='';proofSaved=false;}
  async function hashReport() { const commitment=JSON.stringify({version:1,report:report.trim(),evidence:evidenceFiles.map(file=>({name:file.name,size:file.size,type:file.type,sha256:file.hash}))}); const digest = await crypto.subtle.digest('SHA-256',new TextEncoder().encode(commitment)); reportHash=hex(digest);proofSaved=false; }
  function saveProof(){if(!reportHash||reportUsage>=reportLimit)return;reportUsage+=1;localStorage.setItem('poke-report-usage',String(reportUsage));const saved=JSON.parse(localStorage.getItem('poke-reports')||'[]') as Array<Record<string,unknown>>;const record={hash:reportHash,report:report.trim(),evidence:evidenceFiles.map(file=>({name:file.name,size:file.size,type:file.type,sha256:file.hash})),createdAt:new Date().toISOString()};localStorage.setItem('poke-reports',JSON.stringify([record,...saved.filter(item=>item.hash!==reportHash)].slice(0,100)));proofSaved=true;}
  async function sendChat() { if(!chatInput.trim()||chatLoading) return; const text=chatInput.trim(); const conversation=[...messages,{role:'user' as const,content:text}]; messages=conversation; chatInput='';chatLoading=true;try { const hash=text.match(/0x[a-fA-F0-9]{64}/)?.[0]?.toLowerCase();const saved=JSON.parse(localStorage.getItem('poke-reports')||'[]') as Array<{hash:string;report:string;evidence:unknown[];createdAt:string}>;const record=hash?saved.find(item=>item.hash.toLowerCase()===hash):null;const context=record?`Poké verified local report context for commitment ${record.hash}:\nReport text:\n${record.report}\nEvidence metadata:\n${JSON.stringify(record.evidence)}\nCreated: ${record.createdAt}\nAssess risk only from this supplied evidence. Clearly separate confirmed observations, risk indicators, missing information, and limitations. The hash itself is only an integrity identifier. Respond in concise plain text without Markdown symbols.`:`No saved Poké report was found for a hash in this question. Never infer risk from a hash alone. Ask the user to save the report in Poké or provide its report text and evidence. Respond in concise plain text without Markdown symbols.`;const requestMessages=[{role:'system',content:context},...conversation.map(m=>({role:m.role,content:m.content}))];const r=await fetch('/api/ai/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({messages:requestMessages})}); const data=await r.json(); messages=[...messages,{role:'assistant',content:data.choices?.[0]?.message?.content || data.error || 'No response returned.'}]; } catch { messages=[...messages,{role:'assistant',content:'The AI gateway is temporarily unavailable.'}]; } finally {chatLoading=false;} }
  async function runScamScan(){if(scamUsage>=scamLimit||(!scamTarget.trim()&&!scamDescription.trim())||scamLoading)return;scamLoading=true;scamError='';scamResult=null;const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),35_000);try{const response=await fetch('/api/ai/scam-synthesis',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({target:scamTarget,description:scamDescription}),signal:controller.signal});const data=await response.json();if(!response.ok)throw new Error(data.error);scamResult=data.analysis;scamUsage+=1;localStorage.setItem('poke-scam-usage',String(scamUsage));localStorage.setItem('poke-scam-scans',JSON.stringify([{target:scamTarget,result:data.analysis,scannedAt:data.scannedAt},...JSON.parse(localStorage.getItem('poke-scam-scans')||'[]')].slice(0,50)));}catch(error){scamError=error instanceof Error&&error.name==='AbortError'?'The scan took too long and was stopped. No scan was deducted. Please try again.':error instanceof Error?error.message:'Scam scan failed.';}finally{clearTimeout(timer);scamLoading=false;}}
</script>

<div class="shell">
  <header>
    <a class="brand" href="/" aria-label="Poké home"><span class="mark">P</span><strong>poké</strong><span class="beta">MVP</span></a>
    <nav aria-label="Primary"><a class="active" href="/">Overview</a><a href="/portfolio">Portfolio</a><a href="/explorer">Explorer</a><a href="/plans">Plans</a></nav>
    <div class="top-actions"><button class="risk" onclick={()=>scamOpen=true}><i></i> Scam detection</button><button class="whistle" onclick={()=>reportOpen=true}>Whistleblow</button><WalletAuth /></div>
  </header>

  <main>
    <section class="command" id="explorer">
      <div><span class="eyebrow">UNIVERSAL WEB3 SEARCH</span><h1>One address.<br/><em>Every chain.</em></h1><p>Inspect balances, NFTs, transactions, and evidence without jumping between explorers.</p></div>
      <form onsubmit={(e)=>{e.preventDefault();inspect()}}><label for="query">Address, transaction, or block</label><div class="search"><span>⌕</span><input id="query" bind:value={query} placeholder="0x address, transaction hash, or block"/><button disabled={loading}>{loading?'Loading…':'Inspect'} <kbd>↵</kbd></button></div><small class:error={notice.toLowerCase().includes('error')}>{notice}</small></form>
    </section>

    <section class="chainbar" aria-label="Networks">
      {#each chains as chain}<button class:active={activeChain.id===chain.id} onclick={()=>activeChain=chain}><span style={`background:${chain.color}`}></span>{chain.name}<small>{chain.id}</small></button>{/each}
    </section>

    <section class="workspace">
      <div class="panel portfolio" id="portfolio">
        <div class="panel-head"><div><span class="eyebrow">PORTFOLIO</span><h2>Cross-chain position</h2></div><span class="live"><i></i> {loading?'Loading':'Live RPC'}</span></div>
        <div class="identity"><div class="avatar">0x</div><div><strong>{inspectedAddress || 'No address selected'}</strong><span>{inspectedAddress ? 'Resolved EVM address':'Enter an address above'}</span></div><button aria-label="Copy address" onclick={()=>inspectedAddress&&navigator.clipboard.writeText(inspectedAddress)}>□</button></div>
        <div class="tabs">{#each ['portfolio','activity','nfts'] as item}<button class:active={tab===item} onclick={()=>tab=item as typeof tab}>{item}</button>{/each}</div>
        {#if tab==='activity' && explorerResult}<div class="balance"><span>Explorer result</span><strong>{String(explorerResult.number || explorerResult.hash || 'Found').slice(0,22)}</strong><small>{String(explorerResult.hash || explorerResult.from || '')}</small></div><div class="result"><pre>{JSON.stringify(explorerResult,null,2)}</pre></div>{:else}<div class="balance"><span>Networks queried</span><strong>{balances.filter(b=>b.status==='ok').length || '—'} / 3</strong><small>Native testnet balances from public RPC providers</small></div><div class="assets"><div class="asset-head"><span>Asset</span><span>Balance</span><span>Status</span></div>{#each chains as chain}{@const balance=balances.find(b=>b.chainId===chain.id)}<div class="asset"><span class="coin" style={`--coin:${chain.color}`}>{chain.symbol[0]}</span><div><strong>{chain.symbol}</strong><small>{chain.name}</small></div><span>{balance?.amount ?? '—'}</span><span>{balance?.status ?? 'waiting'}</span></div>{/each}</div>{/if}
      </div>

      <aside>
        <div class="panel risk-card"><div class="panel-head"><div><span class="eyebrow">SCAM DETECTION</span><h2>Evidence first</h2></div><span class="unknown">{scamUsage}/{scamLimit} USED</span></div><div class="gauge"><div>{scamResult?.riskLevel?.[0]?.toUpperCase()||'?'}</div><p>{scamResult?`${scamResult.scamType} risk`:'Submit a suspicious target'}<span>{scamResult?.summary||'Scan a wallet, contract, URL, domain, message, or investment offer.'}</span></p></div>{#each (riskEvidence.length?riskEvidence:[{label:'Target classification',status:'unknown',detail:'Awaiting input'},{label:'User evidence',status:'unknown',detail:'Add suspicious behavior'},{label:'Gonka synthesis',status:'unknown',detail:'Runs after submission'}]) as row}<div class="check"><span>{row.status==='pass'?'✓':'○'}</span><strong>{row.label}</strong><small>{row.detail}</small></div>{/each}<button class="full scam-submit" onclick={()=>scamOpen=true}>Start scam scan</button></div>
        <div class="panel attest"><span class="eyebrow">TAMPER-EVIDENT REPORTS</span><h2>Anchor the proof,<br/>protect the person.</h2><p>Report content is hashed in your browser. Only the proof is anchored on-chain.</p><button onclick={()=>reportOpen=true}>Create a report <span>→</span></button></div>
      </aside>
    </section>
  </main>

  <button class="chat-fab" onclick={()=>chatOpen=!chatOpen}><span>✦</span><div><strong>Chatbot corner</strong><small>Powered by GonkaRouter</small></div><b>↑</b></button>
  {#if chatOpen}<section class="chat"><header><div><span>✦</span><div><strong>Poké assistant</strong><small>Context: {activeChain.name}</small></div></div><button onclick={()=>chatOpen=false}>×</button></header><div class="messages" aria-live="polite">{#each messages as m}<p class={m.role}>{m.content}</p>{/each}{#if chatLoading}<p class="assistant typing">Checking saved evidence…</p>{/if}</div><form onsubmit={(e)=>{e.preventDefault();sendChat()}}><input bind:value={chatInput} placeholder="Ask about this view…" aria-label="Chat message" disabled={chatLoading}/><button disabled={chatLoading} aria-label="Send message">↑</button></form></section>{/if}
  {#if scamOpen}<div class="modal scam-modal" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget&&!scamLoading)scamOpen=false}}><div class="scam-dialog" role="dialog" aria-modal="true" aria-labelledby="scam-title"><button class="close" onclick={()=>scamOpen=false} disabled={scamLoading}>×</button><span class="eyebrow">GONKA-ASSISTED SCAM DETECTION</span><h2 id="scam-title">Scan a suspicious target</h2><div class="quota-line"><span>{plan==='premium'?'Premium':'Free'} plan</span><strong>{scamUsage} / {scamLimit} scans used</strong><a href="/plans">Manage plan</a></div><p>Submit the strongest information you have. Poké combines deterministic checks with GonkaRouter analysis and always shows limitations.</p><form onsubmit={(e)=>{e.preventDefault();runScamScan()}}><label for="scam-target">Wallet, contract, domain, URL, or project name</label><input id="scam-target" bind:value={scamTarget} placeholder="0x…, suspicious-site.example, or project name" maxlength="500"/><label for="scam-description">What happened or looked suspicious?</label><textarea id="scam-description" bind:value={scamDescription} placeholder="Example: The site promised guaranteed returns and asked me to approve unlimited token spending…" maxlength="3000"></textarea>{#if scamUsage>=scamLimit}<p class="limit-warning">Your monthly scam-scan limit has been reached. Upgrade to Premium for more scans.</p>{/if}{#if scamError}<p class="limit-warning">{scamError}</p>{/if}<button class="scam-run" disabled={scamLoading||scamUsage>=scamLimit||(!scamTarget.trim()&&!scamDescription.trim())}>{scamLoading?'Running evidence checks… up to 30 seconds':'Submit and scan · uses 1 scan'}</button></form>{#if scamResult}<section class="scan-output" aria-live="polite"><div class="scan-verdict"><div class={`risk-orb ${scamResult.riskLevel}`}>{scamResult.riskLevel.slice(0,1).toUpperCase()}</div><div><small>RISK LEVEL</small><h3>{scamResult.riskLevel}</h3><span>{scamResult.confidence} confidence</span></div><div class="scam-type"><small>LIKELY SCAM TYPE</small><strong>{scamResult.scamType}</strong></div></div><p class="scan-summary">{scamResult.summary}</p><div class="scan-evidence"><h4>Evidence and indicators</h4>{#if scamResult.evidence.length}<ul>{#each scamResult.evidence as item}<li><span>!</span>{item}</li>{/each}</ul>{:else}<p>No confirmed evidence was available.</p>{/if}</div><div class="scan-guidance"><div class="avoidance"><h4>1. How to avoid this scam</h4><p>Use these checks before connecting, signing, or sending funds.</p><ul>{#each scamResult.avoidance as item}<li><span>○</span>{item}</li>{/each}</ul></div><div class="protection"><h4>2. How to protect yourself now</h4><p>Use these actions if you already clicked, connected, or approved something.</p><ul>{#each scamResult.protection as item}<li><span>✓</span>{item}</li>{/each}</ul></div></div><details><summary>Missing information and limitations</summary><ul>{#each scamResult.missingInformation as item}<li>{item}</li>{/each}</ul><p>{scamResult.disclaimer}</p></details></section>{/if}</div></div>{/if}
  {#if reportOpen}<div class="modal" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)reportOpen=false}}><div class="report-dialog" role="dialog" aria-modal="true" aria-labelledby="report-title"><button class="close" onclick={()=>reportOpen=false}>×</button><span class="eyebrow">WHISTLEBLOWING VERIFICATION</span><h2 id="report-title">Create tamper-evident proof</h2><div class="quota-line"><span>{plan==='premium'?'Premium':'Free'} plan</span><strong>{reportUsage} / {reportLimit} reports · {evidenceFiles.length} / {fileLimit} files</strong><a href="/plans">Manage plan</a></div><p>Your report and files stay in this browser. Poké hashes the report text and every evidence file into one tamper-evident commitment.</p><label for="report">Report content</label><textarea id="report" bind:value={report} oninput={()=>{reportHash='';proofSaved=false}} placeholder="Describe what happened. Avoid including identifying details…"></textarea><div class="evidence-upload"><div><strong>Evidence attachments</strong><small>PNG, JPG, WEBP, PDF, TXT or JSON · 10 MB maximum each</small></div><label class="upload-button" for="evidence">{hashingFiles?'Hashing…':'+ Add files'}</label><input id="evidence" type="file" multiple accept=".png,.jpg,.jpeg,.webp,.pdf,.txt,.json" onchange={addEvidence} disabled={hashingFiles||evidenceFiles.length>=fileLimit}/></div>{#if fileError}<p class="limit-warning">{fileError}</p>{/if}{#if evidenceFiles.length}<div class="evidence-list">{#each evidenceFiles as file}<div><span class="file-icon">{file.type.includes('image')?'IMG':file.type.includes('pdf')?'PDF':'DOC'}</span><p><strong>{file.name}</strong><small>{(file.size/1024).toFixed(1)} KB · SHA-256 {file.hash.slice(0,14)}…</small></p><button aria-label={`Remove ${file.name}`} onclick={()=>removeEvidence(file.id)}>×</button></div>{/each}</div>{/if}<button class="full primary" onclick={hashReport} disabled={!report.trim()||reportUsage>=reportLimit||hashingFiles}>Generate report + evidence hash</button>{#if reportUsage>=reportLimit}<p class="limit-warning">Monthly limit reached. Upgrade your plan to submit more reports.</p>{/if}{#if reportHash}<div class="hash"><small>Combined SHA-256 commitment</small><code>{reportHash}</code><p>This commitment changes if the report text or any attached evidence file changes.</p></div><button class="full primary" onclick={saveProof} disabled={proofSaved||reportUsage>=reportLimit}>{proofSaved?'Proof saved':'Save proof · uses 1 report'}</button>{/if}</div></div>{/if}
</div>
